struct Params {
    N: u32,
    K: u32,
    K_blocks: u32,
    _pad: u32,
}

@group(0) @binding(0) var<storage, read> input: array<f32>;
@group(0) @binding(1) var<storage, read> q6k_data: array<u32>;
@group(0) @binding(2) var<storage, read_write> output: array<f32>;
var<push_constant> params: Params;

fn read_byte(byte_off: u32) -> u32 {
    let word_idx = byte_off / 4u;
    let byte_idx = byte_off % 4u;
    let val = q6k_data[word_idx];
    return (val >> (byte_idx * 8u)) & 0xFFu;
}

fn signed_byte(b: u32) -> i32 {
    return i32(b) - select(0, 256, b >= 128u);
}

fn fp16_to_f32(bits: u32) -> f32 {
    let sign = (bits >> 15u) & 1u;
    let exp = (bits >> 10u) & 0x1Fu;
    let frac = bits & 0x3FFu;

    if (exp == 0u) {
        if (frac == 0u) {
            return select(0.0, -0.0, sign == 1u);
        }
        // Subnormal
        let f = f32(frac);
        let s = select(-1.0, 1.0, sign == 0u);
        // Normalize subnormal: shift left until leading 1, adjust exp
        // GGUF fp16 subnormals are rare but handled by standard conversion
        // Standard way: (1.0 + f/1024.0) * 2^(-14) * sign
        // However, simpler to use bit manipulation or standard formula
        // Let's use the standard formula for robustness
        return s * f32(frac) * 6.103515625e-5; // 2^-14 / 1024
    }

    if (exp == 0x1Fu) {
        if (frac == 0u) {
            return select(-infinity(), infinity(), sign == 0u);
        }
        return nan();
    }

    let f32_exp = i32(exp) - 15 + 127;
    let f32_bits = (sign << 31u) | (u32(f32_exp) << 23u) | (frac << 13u);
    return bitcast<f32>(f32_bits);
}

